package com.vandorlabs.neoforge;
import com.vandorlabs.render.*;
import com.vandorlabs.segmented.SegmentedPanelMesh;
import com.vandorlabs.neoforge.trapdoor.NativeTrapdoorSettings;
import net.minecraft.client.*;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.texture.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
/** Small actual atlas/active-consumer draw; no world, host, grouping or gameplay activation claim. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeTrapdoorRenderChecks {
 private static NativeTrapdoorMesh[] meshes;private static NativeTrapdoorMesh full;private static double[][][] corners;private static final double[][] SCRATCH=new double[8][3];private static int frames,generation;private static int[] negative;private static boolean capture,done;
 private static void need(boolean value,String message){if(!value)throw new AssertionError("Trapdoor GPU: "+message);}
 private static SegmentedPanelMesh.Texture texture(ProgrammableModel.MaterialSnapshot value){var s=value.sprite();need(!s.contents().name().getPath().equals("missingno"),"actual material "+s.contents().name());float u0=s.getU0(),u1=u0+(s.getU1()-u0)*value.usedU(),v0=s.getV0(),v1=v0+(s.getV1()-v0)*value.usedV();return new SegmentedPanelMesh.Texture(){public float u(double pixel){return u0+(u1-u0)*(float)pixel/16F;}public float v(double pixel){return v0+(v1-v0)*(float)pixel/16F;}};}
 private static void prepare(){var bake=NativePanelPlaybackRenderer.currentBake();need(bake!=null,"shared material bake");var artwork=texture(bake.surfaces.get(NativeTrapdoorSettings.defaultTexture()));var edge=texture(bake.originalMetal.surface());int frame=-1;for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(ModernFinishCatalog.ENTRIES.get(i).id().contains("lights_cyan_1")&&ModernFinishCatalog.ENTRIES.get(i).frame()!=null){frame=i;break;}need(frame>=0,"authored cyan frame");var frameArtwork=texture(bake.surfaces.get(ModernFinishCatalog.storedChoice(frame)));double aspect=ModernFinishCatalog.ENTRIES.get(frame).frame().aspect();meshes=new NativeTrapdoorMesh[8];corners=new double[8][][];
  for(int scene=0;scene<8;scene++){boolean tall=scene==3||scene==4||scene==7;int first=tall?2:0,v=tall?1:2;double[][] uv=new double[8][3];for(int i=0;i<8;i++){uv[i][0]=(i&1)==0?0:scene==2?2.5:1;uv[i][v]=(i&(1<<v))==0?0:scene==2?1.75:1;uv[i][tall?2:1]=(i&(tall?4:2))==0?0:1;}
   corners[scene]=scene<3||scene==6?TrapdoorGeometry.corners(1,scene==1,0,scene==1?.65:scene==2?.42:0):DiagonalTrapdoorGeometry.corners(scene==5?2:scene==4?1:0,scene==4,0,false,scene==4,scene==7?0:.4);
   if(scene>=6)meshes[scene]=NativeTrapdoorMesh.frame(TrapdoorFrameLayout.build(uv,first,false,first==0?3/16D:2/16D,scene==7?5:0,new double[]{.08,.12,.06,.09},aspect),frameArtwork,edge);
   else meshes[scene]=NativeTrapdoorMesh.surface(TrapdoorSurfaceLayout.build(uv,first,first+2,scene==2,scene==2,false),artwork,artwork);
   if(scene==6)full=NativeTrapdoorMesh.surface(TrapdoorSurfaceLayout.build(uv,0,2,false,false,false),artwork,artwork);
  }
 }
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(done||!"true".equals(System.getenv("VANDOR_TRAPDOOR_RENDER_CHECK"))||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(meshes==null)prepare();var gui=event.getGuiGraphics();gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();for(int scene=0;scene<8;scene++){int x=10+(scene%4)*155,y=10+(scene/4)*175;gui.enableScissor(x,y,x+150,y+165);var poses=gui.pose();poses.pushPose();try{poses.translate(x+34,y+88,300);poses.scale(70,-70,70);poses.mulPose(com.mojang.math.Axis.XP.rotationDegrees(scene==3||scene==4||scene==7?12:60));(scene==6&&frames<5?full:meshes[scene]).emit(corners[scene],SCRATCH,poses.last(),buffers.getBuffer(RenderType.entityCutoutNoCull(TextureAtlas.LOCATION_BLOCKS)),0xf000f0,OverlayTexture.NO_OVERLAY);}finally{poses.popPose();}buffers.endBatch();gui.flush();gui.disableScissor();}capture=++frames>=10;}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||(!capture&&frames!=5))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double scale=mc.getWindow().getGuiScale();int w=(int)(150*scale),h=(int)(165*scale),x0=(int)(320*scale),y0=(int)(185*scale);if(frames==5){negative=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)negative[y*w+x]=image.getPixelRGBA(x0+x,y0+y);return;}done=true;int changed=0,center=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(negative[y*w+x]!=image.getPixelRGBA(x0+x,y0+y)){changed++;if(x>=65*scale&&x<75*scale&&y>=105*scale&&y<115*scale)center++;}need(changed>200&&center>40,"frame aperture negative changed="+changed+" center="+center);for(int scene=0;scene<8;scene++){int ink=0,x0s=(int)((10+(scene%4)*155)*scale),y0s=(int)((10+(scene/4)*175)*scale);for(int y=0;y<h;y++)for(int x=0;x<w;x++)if((image.getPixelRGBA(x0s+x,y0s+y)&0xffffff)!=0x302820)ink++;need(ink>50,"visible scene="+scene+" ink="+ink);}var path=mc.gameDirectory.toPath().resolve("screenshots/trapdoor-native-"+generation+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);System.out.println("[vandorlabs][trapdoor-render] aperturePixels="+changed+" center="+center+" generation="+generation);}if(generation++==0){meshes=null;frames=0;capture=false;done=false;mc.reloadResourcePacks();return;}System.out.println("[vandorlabs][trapdoor-render] title PASS scenes=8 regular/sliding/mirrored tiles/all diagonal modes/asymmetric frame aperture/join mask/reload; backend only no host claim");mc.stop();}
}
